"""Migrated OPP_MASTER validation rules from legacy/opportunity_rules.vrl."""

from decimal import Decimal
from typing import Any


def _value(row: dict | None, column: str) -> Any:
    """Return a legacy field value; missing and None are empty."""
    if row is None:
        return ""
    value = row.get(column, "")
    return "" if value is None else value


def _numeric(value: Any) -> Decimal:
    """Apply legacy numeric coercion, where empty values compare as zero."""
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def _nvl(value: Any, default: Any) -> Any:
    """Implement legacy NVL: empty, missing, and None select the default."""
    return default if value is None or value == "" else value


def _date_greater_equal(left: Any, right: Any) -> bool:
    """Compare legacy YYYYMMDD dates, respecting the null-date sentinel."""
    left = "" if left is None else str(left)
    right = "" if right is None else str(right)
    if left == "00000000" or right == "00000000":
        return False
    return left >= right


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an OPP_MASTER post-write image in legacy rule-file order."""
    errors: list[dict] = []

    stat_cd = _value(record, "STAT_CD")
    amt = _value(record, "AMT")
    lost_rsn = _value(record, "LOST_RSN")
    close_dt = _value(record, "CLOSE_DT")
    stage_pct = _value(record, "STAGE_PCT")

    def add(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append({"code": code, "message": message, "severity": severity})

    # OPP-001
    if event in ("INSERT", "UPDATE"):
        if _numeric(_nvl(amt, 0)) < Decimal("0"):
            add("E3001", "Amount negative")

    # OPP-002
    if event in ("INSERT", "UPDATE"):
        if stat_cd == "W" and _numeric(_nvl(amt, 0)) == Decimal("0"):
            add("E3002", "Won opportunity requires amount")

    # OPP-003
    if event in ("INSERT", "UPDATE"):
        if stat_cd == "L" and lost_rsn == "":
            add("E3003", "Lost reason required")

    # OPP-004
    if event in ("INSERT", "UPDATE"):
        if stat_cd == "W" and close_dt == "00000000":
            add("E3004", "Won opportunity requires close date")

    # OPP-005
    if event == "UPDATE":
        old_stat_cd = _value(old, "STAT_CD")
        if old_stat_cd == "W" and stat_cd != "W":
            add("E3005", "Cannot reopen a won opportunity")

    # OPP-006
    if event in ("INSERT", "UPDATE"):
        stage = _numeric(stage_pct)
        valid_stage = (
            (stat_cd == "P" and stage == Decimal("10"))
            or (stat_cd == "Q" and stage == Decimal("25"))
            or (stat_cd == "N" and stage == Decimal("60"))
            or (stat_cd == "W" and stage == Decimal("100"))
            or (stat_cd == "L" and stage == Decimal("0"))
        )
        if not valid_stage:
            add("E3006", "Stage percent inconsistent with status")

    # OPP-007
    if event == "INSERT":
        if not (close_dt == "00000000" or _date_greater_equal(close_dt, today)):
            add("E3007", "Close date in past", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure is blocking."""
    return any(error.get("severity") == "BLOCK" for error in errors)
